/* 孤星问道 · 万妖塔 | 九色琉璃，30° 斜俯视 */
(function () {
"use strict";
const sealModule = {};
// Each endpoint is the junction of two engraved strokes on the original seal painting.
const BloodPillars = (() => {
  const flat=.335, groundRadius=278, groundY=40, tilt=Math.PI/6;
  const skyRadius=145, skyY=-791;
  const groundTips=[[450,58],[757,137],[757,279],[450,357],[143,279],[143,137]];
  const skyTips=[[412,27],[618,81],[542,161],[268,178],[59,125],[141,45]];
  const beams=groundTips.map(([px,py],i)=>{
    const x=(px-450)*groundRadius/400, z=(py-207)*groundRadius/164;
    const footX=x*Math.cos(tilt)-z*Math.sin(tilt);
    const depth=x*Math.sin(tilt)+z*Math.cos(tilt);
    const footY=groundY+flat*depth;
    const headX=(skyTips[i][0]-340)*skyRadius/310;
    const headY=skyY+(skyTips[i][1]-102)*skyRadius*flat/87;
    const dx=headX-footX,dy=headY-footY,length=Math.hypot(dx,dy);
    return {footX,footY,headX,headY,length,tx:dx/length,ty:dy/length,near:i>=1&&i<=3};
  });
  const sigils=new Image();
  const inscriptions=document.createElement('canvas');
  function illuminateStrokes() {
    inscriptions.width=sigils.width;inscriptions.height=sigils.height;
    const paint=inscriptions.getContext('2d');
    paint.drawImage(sigils,0,0);
    paint.globalCompositeOperation='source-atop';
    paint.fillStyle='rgba(255,99,77,.80)';paint.fillRect(0,0,inscriptions.width,inscriptions.height);
  }
  const ready=new Promise((ok,fail)=>{
    sigils.onload=()=>{illuminateStrokes();ok();};sigils.onerror=()=>fail(new Error('光柱符文读取失败'));
    sigils.src=new URL('assets/runes/seal-blood.webp',document.currentScript?.src||document.baseURI).href;
  });
  // Paint six translucent, narrow volumes once. Each has a soft exterior and
  // several uneven strands of blood light surfacing along its length.
  const width=88,height=870;
  const sheet=document.createElement('canvas');sheet.width=6*width;sheet.height=height;
  const ink=sheet.getContext('2d'), pixels=ink.createImageData(sheet.width,height);
  const bell=(d,w)=>Math.exp(-d*d/(w*w));
  for(let i=0;i<6;i++){
    for(let y=0;y<height;y++){
      const u=y/(height-1),radius=7.3+5.1*u,phase=8.8*u+i*1.65;
      const fold=radius*.40*Math.sin(phase)+1.1*Math.sin(24*u+i);
      const grain=.90+.10*Math.cos(25*u+i);
      for(let x=0;x<width;x++){
        const d=x+.5-width/2;
        const shell=bell(d,radius*1.13), mist=bell(d,radius*1.83);
        const left=bell(d+radius*.67-.8*Math.sin(17*u+i),1.3);
        const right=bell(d-radius*.64-.9*Math.sin(19*u-i),1.15);
        const core=bell(d-fold,1.4)+.45*bell(d+fold*.8,2.2);
        const rim=(left*.74+right*.85)*grain;
        const a=Math.min(.9,.15*mist+.31*shell+.29*rim+.30*core);
        const p=(y*sheet.width+i*width+x)*4;
        pixels.data[p]=153+59*shell+25*rim+13*core;
        pixels.data[p+1]=7+7*shell+21*rim+31*core;
        pixels.data[p+2]=28+7*shell+19*rim+17*core;
        pixels.data[p+3]=Math.round(255*a);
      }
    }
  }
  ink.putImageData(pixels,0,0);
  const ember=document.createElement('canvas');ember.width=ember.height=64;
  const brush=ember.getContext('2d'),glow=brush.createRadialGradient(32,32,0,32,32,32);
  for(const [p,c] of [[0,'#ffd6a8'],[.10,'#ff9b83f0'],[.28,'#ff4b5aa0'],[.58,'#e51c3848'],[1,'#9b112b00']])glow.addColorStop(p,c);
  brush.fillStyle=glow;brush.fillRect(0,0,64,64);
  function ground(ctx,image,alpha) {
    ctx.save();ctx.globalAlpha*=alpha;ctx.translate(0,groundY);
    ctx.scale(1,flat);ctx.rotate(tilt);
    ctx.drawImage(image,-450*groundRadius/400,-207*groundRadius/164,900*groundRadius/400,414*groundRadius/164);
    ctx.restore();
  }
  function draw(ctx,t,levels,near) {
    if(!sigils.naturalWidth)return;
    ctx.save();
    const alpha=ctx.globalAlpha;
    ctx.globalCompositeOperation='lighter';
    for(const [i,b] of beams.entries()){
      if(b.near!==near)continue;
      const beat=.5+.5*Math.cos(t*(1.38+.033*i)+i*1.82);
      const power=(near?.83:.69)*(1-.20*levels[8]);
      ctx.save();
      // The local y-axis runs from the sky tip to the ground tip.
      ctx.transform(-b.ty,b.tx,-b.tx,-b.ty,b.headX,b.headY);
      ctx.globalAlpha=alpha*power*(.84+.14*beat);
      ctx.drawImage(sheet,i*width,0,width,height,-width/2,0,width,b.length);
      const direction=i%2?1:-1;
      for(let j=0;j<6;j++){
        const phase=(j/6+i*.131+direction*t*(.022+i*.00055))%1;
        const u=phase<0?phase+1:phase;
        const fade=Math.min(1,u*28,(1-u)*28);
        const x=2.3*Math.sin(9*u+i),size=23+4*u;
        const col=1+(j+2*i)%5,row=(2*j+i)%9;
        // Crop to a single painted stamp, preserving its soft edge.
        ctx.globalAlpha=alpha*power*fade*.14;
        ctx.drawImage(ember,x-size*.84,u*b.length-size*.57,size*1.68,size*1.14);
        ctx.globalAlpha=alpha*power*fade*(.90+.10*beat);
        ctx.drawImage(inscriptions,144*col+34,80*row+1,76,78,x-size*.52,u*b.length-size*.54,size*1.04,size*1.08);
      }
      // A slower, longer pulse runs under the engraved characters.
      const p=(t*(.092+.002*i)+i*.17)%1, along=direction<0?1-p:p;
      ctx.globalAlpha=alpha*power*.44*Math.min(1,p*12,(1-p)*12);
      ctx.drawImage(ember,-8,along*b.length-34,16,68);
      ctx.restore();
      for(const [x,y,r] of [[b.footX,b.footY,22],[b.headX,b.headY,12.5]]){
        ctx.globalAlpha=alpha*power*(.79+.21*beat);
        ctx.drawImage(ember,x-r,y-r*.46,2*r,r*.92);
      }
    }
    ctx.restore();
  }
  return {ready,ground,draw};
})();

/* Boss seal colours, ordered from the gate to the crown. Each ramp describes the
   shadow inside the glass, its body colour, a transmitting edge and its glint. */
const TowerPalette = [
  { name:'绯红', boss:'绛蘅', deep:[53,5,24], mid:[232,42,80], light:[255,116,144], core:[255,223,214] },
  { name:'霜白', boss:'玄锋', deep:[37,71,89], mid:[190,216,226], light:[203,242,250], core:[248,255,255] },
  { name:'冰蓝', boss:'霁月', deep:[11,28,77], mid:[50,155,242], light:[102,207,255], core:[218,247,255] },
  { name:'赤金', boss:'焚羽', deep:[68,17,13], mid:[253,96,43], light:[255,162,65], core:[255,231,166] },
  { name:'琥珀', boss:'玄岳', deep:[76,44,8], mid:[235,162,45], light:[255,205,91], core:[255,247,198] },
  { name:'幽紫', boss:'殷无赦', deep:[40,15,70], mid:[153,83,225], light:[202,146,255], core:[241,219,255] },
  { name:'青碧', boss:'', deep:[8,55,55], mid:[47,190,157], light:[109,247,198], core:[218,255,230] },
  { name:'墨金', boss:'', deep:[18,24,31], mid:[114,98,58], light:[210,167,79], core:[255,226,157] },
  { name:'星白', boss:'', deep:[71,53,92], mid:[226,218,241], light:[244,225,255], core:[255,251,238] }
];

/* Painted octagonal turntables, generated from an orthographically projected mesh.
   All dimensions below use the tower's local ground-centre coordinate system. */
const TowerBody = (() => {
  "use strict";
  const source = document.currentScript && document.currentScript.src;
  const assetDir = new URL("assets/tower/", source || document.baseURI);
  const images = Object.create(null);
  const materials = ["gallery", "gate", "summit"];
  const required = ["plinth", "stairs", "jewel-dark", "jewel-lit"];
  for (const material of materials) required.push(material + "-dark", material + "-lit");
  let loaded = false;

  function load(name) {
    return new Promise((resolve, reject) => {
      const picture = new Image();
      picture.onload = () => { images[name] = picture; resolve(); };
      picture.onerror = () => reject(new Error("塔身素材加载失败 " + picture.src));
      picture.src = new URL(name + ".webp", assetDir).href;
    });
  }

  const ready = Promise.all(required.map(load)).then(() => { loaded = true; });
  const stepCount = 56;
  const columns = 8;
  const octant = Math.PI / 4;
  // Thirty-degree orthographic map camera. h is projected height; every storey
  // uses one uniform XY sprite scale, preserving the same horizontal depth axis.
  const depthScale = 0.5;
  const layouts = {
    gallery: { width:216, height:169, originX:108, originY:125, pixels:1, modelHeight:70, eaveY:49.2 },
    gate:    { width:252, height:212, originX:126, originY:161, pixels:1.18, modelHeight:82.4, eaveY:61.5 },
    summit:  { width:146, height:145, originX:73, originY:114, pixels:.665, modelHeight:95/.60, eaveY:43.5 }
  };
  for (const kind of materials) {
    const tile = layouts[kind];
    const canvas = document.createElement("canvas");
    canvas.width = tile.width;
    canvas.height = tile.height;
    tile.scratch = canvas;
    tile.painter = canvas.getContext("2d");
  }

  // Storeys share a pivot, while each keeps its own height, radius, speed and azimuth.
  // Nine concentric eaves. The crown spans 48% of the gate, with the same reduction
  // at each step. This also leaves room for the apparent width change of an octagon.
  const bottomRadius = 125;
  const crownRadius = 60;
  const storeyRatio = Math.pow(crownRadius / bottomRadius, 1 / 8);
  let nextBase = -26;
  const floors = [
    ["gate",   20.7,.22], ["gallery",-16.5,.09], ["gallery",18.2,.30],
    ["gallery",-15.9,.12], ["gallery",20,.25], ["gallery",-16.8,.06],
    ["gallery",19.4,.27], ["gallery",-16.3,.10], ["summit",22,.21]
  ].map(([kind, period, phase], index) => {
    const radius = bottomRadius * Math.pow(storeyRatio, index);
    const tile = layouts[kind];
    const base = nextBase;
    const height = tile.modelHeight * radius / 100;
    nextBase -= height;
    const sx = radius / (100 * tile.pixels);
    const palette = TowerPalette[index];
    const glaze = tile.painter.createLinearGradient(0, 0, 0, tile.height);
    glaze.addColorStop(0, rgb(palette.deep));
    glaze.addColorStop(.33, rgb(palette.mid));
    glaze.addColorStop(.64, rgb(palette.light));
    glaze.addColorStop(.82, rgb(palette.mid));
    glaze.addColorStop(1, rgb(palette.deep));
    return { kind, tile, base, radius, height, period, phase, palette, glaze, reflections: [null, null],
      dx: -tile.originX * sx, dy: base - tile.originY * sx,
      dw: tile.width * sx, dh: tile.height * sx };
  });
  const anchors = floors.map((floor) => {
    const ringY = floor.base - floor.height * (floor.kind === "summit" ? .175 : .44);
    return { y: ringY, r: floor.radius * .775, eaveR: floor.radius,
      eaveY: floor.base - floor.tile.eaveY * floor.radius / 100,
      depthScale, ringY, baseY: floor.base, height: floor.height };
  });

  // Blend the two surrounding angles in premultiplied alpha. Adding them on an
  // isolated transparent surface preserves coverage at railings, bells and roof tips.
  function sample(tile, atlas, frame, weight) {
    if (weight <= 0) return;
    const ctx = tile.painter;
    ctx.globalAlpha = weight;
    const x = (frame % columns) * tile.width;
    const y = Math.floor(frame / columns) * tile.height;
    ctx.drawImage(atlas, x, y, tile.width, tile.height, 0, 0, tile.width, tile.height);
  }
  function rgb(triplet) {
    return "rgb(" + triplet.join(",") + ")";
  }

  function blendAngles(tile, atlas, before, after, f) {
    const p = tile.painter;
    p.clearRect(0, 0, tile.width, tile.height);
    p.globalCompositeOperation = "lighter";
    sample(tile, atlas, before, 1 - f);
    sample(tile, atlas, after, f);
    p.globalAlpha = 1;
  }

  // The 56-step octant has an even number of samples. Consecutive angles,
  // including 55 -> 0, always occupy different slots. Each floor therefore
  // retains the same two tiny colour plates across all interstitial frames.
  function reflection(floor, frame) {
    const slot = frame % 2;
    const tile = floor.tile;
    let cached = floor.reflections[slot];
    if (!cached) {
      const canvas = document.createElement("canvas");
      canvas.width = tile.width;
      canvas.height = tile.height;
      cached = { canvas, ctx: canvas.getContext("2d"), frame: -1 };
      floor.reflections[slot] = cached;
    }
    if (cached.frame === frame) return cached.canvas;

    const ctx = cached.ctx;
    const x = (frame % columns) * tile.width;
    const y = Math.floor(frame / columns) * tile.height;
    ctx.globalCompositeOperation = "copy";
    ctx.drawImage(images[floor.kind + "-lit"], x, y, tile.width, tile.height, 0, 0, tile.width, tile.height);
    ctx.globalCompositeOperation = "source-in";
    ctx.fillStyle = floor.glaze;
    ctx.fillRect(0, 0, tile.width, tile.height);
    cached.frame = frame;
    return cached.canvas;
  }

  function drawFloor(ctx, floor, phase, light) {
    const tile = floor.tile;
    const frame = phase * stepCount;
    const before = Math.floor(frame);
    const after = (before + 1) % stepCount;
    const fraction = frame - before;
    // The ink and bronze surfaces remain dark throughout the encounter.
    blendAngles(tile, images[floor.kind + "-dark"], before, after, fraction);
    ctx.drawImage(tile.scratch, floor.dx, floor.dy, floor.dw, floor.dh);
    if (light <= 0) return;

    // A fixed medium colour multiplied by an interpolated mask equals the
    // weighted sum of the two coloured masks in premultiplied space.
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    const alpha = ctx.globalAlpha * light * .72;
    ctx.globalAlpha = alpha * (1 - fraction);
    ctx.drawImage(reflection(floor, before), floor.dx, floor.dy, floor.dw, floor.dh);
    if (fraction > 0) {
      ctx.globalAlpha = alpha * fraction;
      ctx.drawImage(reflection(floor, after), floor.dx, floor.dy, floor.dw, floor.dh);
    }
    ctx.restore();
  }

  function sweep(ctx, floor, phase, age) {
    if (!(age >= 0 && age < 1.35)) return;
    const prog = age / 1.35;
    const ease = prog * prog * (3 - 2 * prog);
    const turn = Math.PI * 2;
    const dir = Math.sign(floor.period);
    const head = dir * (-1.12 + ease * turn);
    const flare = Math.min(1, age * 12, (1.35 - age) * 9);
    const sy = floor.height / floor.tile.modelHeight;
    const palette = floor.palette;
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    const alpha = ctx.globalAlpha;
    ctx.lineJoin = "round";
    ctx.lineCap = "round";
    // Trace the front-facing eaves. As the head travels around the far half,
    // that part of the arc is occluded by the roof and upper storey.
    for (let k = 0; k < 8; k++) {
      const center = (k + phase) * octant;
      if (Math.cos(center) <= 0) continue;
      const a = center - octant / 2, b = center + octant / 2;
      const x1 = Math.sin(a), x2 = Math.sin(b);
      const z1 = Math.cos(a), z2 = Math.cos(b);
      const gradient = ctx.createLinearGradient(x1 * floor.radius, 0, x2 * floor.radius, 0);
      let highest = 0;
      ctx.beginPath();
      for (let i = 0; i <= 16; i++) {
        const u = i / 16;
        const x = x1 + (x2 - x1) * u;
        const z = z1 + (z2 - z1) * u;
        const curve = (floor.kind === "summit" ? 14.8 : 13.3) * Math.pow(Math.abs(2 * u - 1), 3.52);
        const y = floor.base + (100 * depthScale * z - floor.tile.eaveY - curve) * sy;
        if (i === 0) ctx.moveTo(x * floor.radius, y);
        else ctx.lineTo(x * floor.radius, y);
        const lag = (dir * (head - Math.atan2(x, z)) + turn * 2) % turn;
        let strength = 0;
        if (lag < 1.04) {
          const ramp = Math.min(1, lag / .115);
          strength = ramp * ramp * (3 - 2 * ramp) * (1 - lag / 1.04) ** 1.25;
        }
        const crystal = Math.min(1, strength * strength * 1.38);
        const r = Math.round(palette.mid[0] + (palette.core[0] - palette.mid[0]) * crystal);
        const g = Math.round(palette.mid[1] + (palette.core[1] - palette.mid[1]) * crystal);
        const b2 = Math.round(palette.mid[2] + (palette.core[2] - palette.mid[2]) * crystal);
        gradient.addColorStop(u, "rgba(" + r + "," + g + "," + b2 + "," + strength + ")");
        highest = Math.max(highest, strength);
      }
      if (highest <= .006) continue;
      ctx.strokeStyle = gradient;
      ctx.globalAlpha = alpha * flare * .32;
      ctx.lineWidth = 4.8 * sy;
      ctx.stroke();
      ctx.globalAlpha = alpha * flare;
      ctx.lineWidth = 1.5 * sy;
      ctx.stroke();
    }
    ctx.restore();
  }

  function draw(ctx, t, levels, ages, hooks) {
    if (!loaded) return;
    ctx.save();
    ctx.imageSmoothingEnabled = true;
    ctx.drawImage(images.plinth, -135, -96);
    for (let i = 0; i < floors.length; i++) {
      const floor = floors[i];
      const run = t / floor.period + floor.phase;
      const phase = run - Math.floor(run);
      const light = Math.max(0, Math.min(1, levels[i]));
      if (hooks && hooks.beforeFloor) hooks.beforeFloor(ctx, i, anchors[i], phase);
      drawFloor(ctx, floor, phase, light);
      sweep(ctx, floor, phase, ages[i]);
      if (hooks && hooks.afterFloor) hooks.afterFloor(ctx, i, anchors[i], phase);
    }
    const alpha = ctx.globalAlpha;
    const lit = levels[8];
    ctx.drawImage(images["jewel-dark"], -18, nextBase - 66);
    if (lit > 0) {
      ctx.globalAlpha = alpha * lit;
      ctx.drawImage(images["jewel-lit"], -18, nextBase - 66);
      ctx.globalAlpha = alpha;
    }
    ctx.drawImage(images.stairs, -36, -8);
    ctx.restore();
  }
  return { anchors, ready, draw };
})();

// Fixed seal irons, four anchor piers, and the two ritual circles.
// All coordinates are relative to the base of the tower. Times are seconds.
(function (global) {
  'use strict';
  const TAU = 2 * Math.PI;
  const clamp = (n, low, high) => Math.max(low, Math.min(high, n));
  // Z is horizontal depth towards the player. On the orthographic tile map
  // its screen projection is sin(30°) = 1/2. All piers share the same physical scale.
  const depthScale = 0.5;
  const piers = [
    { x: -340, z: -194, height: 86, rear: true },
    { x:  345, z: -182, height: 86, rear: true },
    { x: -352, z:  212, height: 86, rear: false },
    { x:  351, z:  225, height: 86, rear: false }
  ].map(p => ({ ...p, y:p.z * depthScale }));
  const artwork = {};
  const ready = Promise.all(Object.entries(sealImageData()).map(([name, bytes]) => new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => { artwork[name] = image; resolve(); };
    image.onerror = () => reject(new Error('Cannot decode seal artwork: ' + name));
    image.src = 'data:image/webp;base64,' + bytes;
  }))).then(prepareSkyLight);

  function surface(width, height) {
    const c = document.createElement('canvas');
    c.width = width;
    c.height = height;
    return c;
  }

  const glows = new Map();
  function glow(ctx, type, x, y, width, height, opacity) {
    if (opacity <= 0 || width <= 0 || height <= 0) return;
    let sprite = glows.get(type);
    if (!sprite) {
      const colors = { rust: ['244,80,27', '185,30,10'], flame: ['255,188,91', '235,70,20'], shadow: ['10,7,13', '18,10,19'] };
      const [hot, cool] = typeof type === 'number'
        ? [TowerPalette[type].light.join(','), TowerPalette[type].mid.join(',')]
        : colors[type];
      sprite = surface(128, 128);
      const g = sprite.getContext('2d');
      const radial = g.createRadialGradient(64, 64, 0, 64, 64, 64);
      radial.addColorStop(0, 'rgba(' + hot + ',0.95)');
      radial.addColorStop(0.23, 'rgba(' + hot + ',0.64)');
      radial.addColorStop(0.57, 'rgba(' + cool + ',0.22)');
      radial.addColorStop(1, 'rgba(' + cool + ',0)');
      g.fillStyle = radial;
      g.fillRect(0, 0, 128, 128);
      glows.set(type, sprite);
    }
    const alpha = ctx.globalAlpha;
    ctx.globalAlpha = alpha * opacity;
    ctx.drawImage(sprite, x - width, y - height, 2 * width, 2 * height);
    ctx.globalAlpha = alpha;
  }

  function stamp(ctx, image, x, y, w, h, opacity) {
    if (!image) return;
    const a = ctx.globalAlpha;
    ctx.globalAlpha *= opacity;
    ctx.drawImage(image, x, y, w, h);
    ctx.globalAlpha = a;
  }

  // The altar catches a soft reflection. The cloud seal gets its own ninth-floor
  // response so the summit has a distinct final state.
  let skyGlass;
  let restingSky;
  let restingGround;

  function recolor(image, colour) {
    const layer = surface(image.width, image.height);
    const c = layer.getContext('2d');
    c.drawImage(image, 0, 0);
    c.globalCompositeOperation = 'source-atop';
    c.fillStyle = colour;
    c.fillRect(0, 0, layer.width, layer.height);
    return layer;
  }

  let skyShafts;
  function prepareSkyLight() {
    if (skyGlass) return;
    skyGlass = recolor(artwork.sky, 'rgba(235,219,255,.92)');
    restingSky = recolor(artwork.sky, 'rgba(124,62,79,.69)');
    restingGround = recolor(artwork.ground, 'rgba(133,49,58,.60)');

    skyShafts = surface(256, 160);
    const light = skyShafts.getContext('2d');
    const field = light.createImageData(skyShafts.width, skyShafts.height);
    for (let y = 0; y < field.height; y++) {
      const v = y / (field.height - 1);
      const fade = Math.min(1, v * 18) * Math.pow(1 - v, 2.3);
      for (let x = 0; x < field.width; x++) {
        const u = x / (field.width - 1) * 2 - 1;
        const left = (u + .59 - .25 * v) / (.07 + .07 * v);
        const right = (u - .61 + .21 * v) / (.085 + .07 * v);
        const middle = (u + .02) / (.31 + .08 * v);
        const rays = .65 * Math.exp(-left*left) + .80 * Math.exp(-right*right) + .26 * Math.exp(-middle*middle);
        const i = 4 * (y * field.width + x);
        field.data[i] = 255;
        field.data[i+1] = 186 + 24 * (1 - Math.abs(u));
        field.data[i+2] = 143 + 42 * (1 - Math.abs(u));
        field.data[i+3] = Math.round(107 * fade * rays);
      }
    }
    light.putImageData(field, 0, 0);
  }

  // Only 620×174 of the 680×288 sky painting is the actual ring; the rest is
  // transparent margin and pendant fire. Warp the rim to an authentic 2:1 ellipse.
  const skyRadius = 145;
  const skyY = -791;
  const skyWidth = skyRadius * 2 * 680 / 620;
  const skyScaleY = skyRadius * 2 * .335 / 174;
  const skyHeight = 288 * skyScaleY;
  const skyTop = skyY - 102 * skyScaleY;

  function sky(ctx, t, energy, crown, rear) {
    if (!artwork.sky) return;
    prepareSkyLight();
    if (rear) {
      glow(ctx, 'rust', 0, skyY + 6, 176, 78, .08 + energy * .08);
      if (crown > 0) glow(ctx, 8, 0, skyY, 154, 82, .25*crown);
      stamp(ctx, skyShafts, -125, skyY-16, 250, 112,
        (.035 + crown * .37) * (.96 + .04 * Math.sin(t*.57)));
      return;
    }
    // The entire horizontal seal is above the spire. At a shared screen pixel
    // that plane is nearer the downward-looking camera. Paint its crystal once
    // to avoid a subpixel split in the central engraving while the map pans.
    ctx.save();
    const settled = .64 + energy * .12;
    if (crown < 1) stamp(ctx, restingSky, -skyWidth/2, skyTop, skyWidth, skyHeight, settled * (1-crown));
    if (crown > 0) stamp(ctx, artwork.sky, -skyWidth/2, skyTop, skyWidth, skyHeight, .87*crown);
    ctx.globalCompositeOperation = 'lighter';
    stamp(ctx, artwork.sky, -skyWidth/2, skyTop, skyWidth, skyHeight, .13 + energy*.145);
    if (crown > 0) {
      stamp(ctx, skyGlass, -skyWidth/2, skyTop, skyWidth, skyHeight, .95*crown);
      stamp(ctx, skyGlass, -skyWidth/2-1.4, skyTop-.68, skyWidth+2.8, skyHeight+1.36, .22*crown);
    }
    ctx.restore();
  }

  // This is a ground marking on the same pavement as the stele. The footprint
  // extends from the tower's apron to the southern edge of the interaction space.
  function ground(ctx, levels) {
    if (!artwork.ground) return;
    const energy=meanLevel(levels);
    ctx.save();
    glow(ctx,'rust',0,40,291,100,.13+energy*.09);
    BloodPillars.ground(ctx,restingGround,.88-.28*energy);
    if (energy>0) BloodPillars.ground(ctx,artwork.ground,.46*energy);
    ctx.restore();
  }

  function pier(ctx, p, energy) {
    const w=p.height*(169/233);
    // The contact ellipse and the cast shadow lie on the sloped ground plane.
    glow(ctx,'shadow',p.x+w*.23,p.y+w*.08,w*1.07,w*.35,.29);
    glow(ctx,'shadow',p.x+w*.06,p.y-1.7,w*.71,w*.19,.72);
    stamp(ctx,artwork.pillar,p.x-w/2,p.y-p.height,w,p.height,p.rear ? .95 : 1);
    glow(ctx,'rust',p.x,p.y-p.height*.49,w*.12,p.height*.2,energy*.39);
    glow(ctx,'flame',p.x-w*.02,p.y-p.height*.48,w*.054,p.height*.13,energy*.32);
  }

  function point(c, u) {
    return {
      x: c.x + (c.ex - c.x) * u,
      y: c.y + (c.ey - c.y) * u + 4 * c.sag * u * (1 - u)
    };
  }

  function orientation(c, u) {
    const angle = Math.atan2(c.ey - c.y + 4 * c.sag * (1 - 2 * u), c.ex - c.x);
    return Math.abs(angle) > Math.PI / 2 ? angle + Math.PI : angle;
  }

  function partPath(path, points, close) {
    path.moveTo(points[0].x, points[0].y);
    for (let j = 1; j < points.length; j++) path.lineTo(points[j].x, points[j].y);
    if (close) path.closePath();
  }

  function oval(path, x, y, rx, ry, angle, from = 0, to = TAU) {
    const c = Math.cos(angle), s = Math.sin(angle);
    path.moveTo(x + Math.cos(from) * rx * c - Math.sin(from) * ry * s,
                y + Math.cos(from) * rx * s + Math.sin(from) * ry * c);
    path.ellipse(x, y, rx, ry, angle, from, to);
  }

  function plate(c, u) {
    const mid = point(c, u), a = orientation(c, u), w = c.size;
    const co = Math.cos(a) * w, si = Math.sin(a) * w;
    const p = (x, y) => ({ x: mid.x + x * co - y * si, y: mid.y + x * si + y * co });
    const coords = [[-6.3,-1.15],[-5.4,-2.05],[5.3,-2.05],[6.5,-1.1],[6.1,1.15],[5.2,1.88],[-5.6,1.88],[-6.5,0.95]];
    partPath(c.plates, coords.map(([x,y]) => p(x,y)), true);
    partPath(c.lip, [p(-6,-1),p(-5.3,-1.7),p(5.1,-1.7),p(5.9,-1.1)], false);
    partPath(c.signs, [p(-3.7,0.6),p(-2.4,-0.64),p(-1.05,0.51),p(0,-0.52),p(1.0,0.54),p(2.4,-0.6),p(3.6,0.62)], false);
  }

  function makeChain(anchor, floor, side) {
    // A different pair of shackles bears the middle floors, breaking mirror symmetry.
    const front = floor < 3 || (floor === 3 && side === 1) || (floor === 4 && side === -1);
    const pierIndex = (side === -1 ? 0 : 1) + (front ? 2 : 0);
    const p = piers[pierIndex];
    const radial = Math.hypot(p.x, p.z);
    // Anchor to a stationary bearing at the actual azimuth of the support.
    // A rear eye recedes up the eave ellipse; a front eye advances down it.
    const lockX = anchor.r * p.x / radial;
    const lockZ = anchor.r * p.z / radial;
    const c = {
      level: floor, front, pierIndex,
      x: lockX, y: anchor.y + lockZ * anchor.depthScale,
      ex: p.x + side * (floor % 3 - 1) * 1.45,
      ey: p.y - p.height * (0.905 - (floor % 2) * 0.015),
      // Sag is the projected vertical deflection of the suspended chain.
      sag: front ? 20 + floor * 3.3 : 26 + (floor - 3) * 3.0,
      size: front ? .96 : .88,
      body: new Path2D(), rim: new Path2D(), glints: new Path2D(), runner: new Path2D(),
      plates: new Path2D(), lip: new Path2D(), signs: new Path2D()
    };
    const distances = [0];
    let last = point(c, 0);
    const segments = 96;
    for (let j = 1; j <= segments; j++) {
      const q = point(c, j / segments);
      distances[j] = distances[j - 1] + Math.hypot(q.x - last.x, q.y - last.y);
      last = q;
    }
    c.length = distances[segments];
    const count = Math.round(c.length / (8.0 * c.size));
    const step = c.length / count;
    let ix = 1;
    for (let j = 0; j <= count; j++) {
      const dist = j * step;
      while (ix < segments && distances[ix] < dist) ix++;
      const u = ((ix - 1) + (dist - distances[ix - 1]) / (distances[ix] - distances[ix - 1])) / segments;
      const q = point(c, u), a = orientation(c, u);
      const rx = step * 0.68, ry = c.size * (j % 2 ? 0.70 : 1.96);
      oval(c.body, q.x, q.y, rx, ry, a);
      oval(c.rim, q.x, q.y - 0.05, rx, ry, a, -2.96, -0.53);
      if ((j + floor) % 4 === 0) oval(c.glints, q.x, q.y, rx, ry, a, -2.73, -1.72);
    }
    c.runner.moveTo(c.x, c.y);
    c.runner.quadraticCurveTo((c.ex + c.x) / 2, (c.ey + c.y) / 2 + c.sag * 2, c.ex, c.ey);
    plate(c, 0.24 + (floor % 3) * 0.025);
    if (c.length > 310) plate(c, 0.68 - (floor % 2) * 0.045);
    return c;
  }

  function stroke(ctx, path, color, width) {
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.stroke(path);
  }

  function darkIron(ctx, c) {
    const s = c.size;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    stroke(ctx, c.body, '#171319', 2.55 * s);
    stroke(ctx, c.body, c.front ? '#4c3631' : '#42343a', 1.45 * s);
    stroke(ctx, c.rim, c.front ? '#756057' : '#66545a', 0.87 * s);
    stroke(ctx, c.glints, c.front ? '#9d7b6b' : '#8b7473', 0.70 * s);
    ctx.fillStyle = '#2b2224';
    ctx.fill(c.plates);
    stroke(ctx, c.plates, '#1c1419', 1.12 * s);
    stroke(ctx, c.lip, '#9c7955', 0.95 * s);
    stroke(ctx, c.signs, '#956b4b', 0.68 * s);
  }

  function litIron(ctx, c, amount) {
    if (amount < 0.001) return;
    const a = ctx.globalAlpha, s = c.size;
    ctx.globalAlpha = a * amount;
    const tint = TowerPalette[c.level];
    stroke(ctx, c.runner, 'rgba(' + tint.mid + ',.035)', s * 5.7);
    stroke(ctx, c.rim, 'rgba(' + tint.mid + (c.front ? ',.52)' : ',.41)'), .88 * s);
    stroke(ctx, c.glints, 'rgba(' + tint.light + ',.69)', .79 * s);
    stroke(ctx, c.lip, 'rgba(' + tint.mid + ',.67)', .87 * s);
    stroke(ctx, c.signs, 'rgba(' + tint.light + ',.94)', .99 * s);
    ctx.globalAlpha = a;
  }

  // Moving stories pass behind fixed attachment eyes. These small ferrules provide
  // a stationary bearing surface; the iron itself never samples the floor angle.
  function eye(ctx, c, bright) {
    const side = Math.sign(c.x);
    const x = c.x, y = c.y, s = c.size;
    const q = new Path2D();
    q.moveTo(x + side * 2, y + 0.6);
    q.lineTo(x - side * 4.8, y + 2.4);
    q.lineTo(x - side * 7.4, y - 0.2);
    q.lineTo(x - side * 4.8, y - 2.4);
    q.closePath();
    ctx.fillStyle = '#35252a'; ctx.fill(q);
    stroke(ctx, q, '#9c775a', 0.72 * s);
    const ring = new Path2D();
    oval(ring, x + side * 0.1, y + 0.3, 2.7 * s, 1.95 * s, side * 0.27);
    stroke(ctx, ring, bright ? 'rgb(' + TowerPalette[c.level].light + ')' : '#665052', 1.05 * s);
  }

  function layer(chains) {
    const xs = chains.flatMap(c => [c.x, c.ex]);
    const ys = [];
    for (const c of chains) for (let j = 0; j <= 20; j++) ys.push(point(c, j / 20).y);
    const x = Math.floor(Math.min(...xs) - 12), y = Math.floor(Math.min(...ys) - 12);
    const w = Math.ceil(Math.max(...xs) - x + 12), h = Math.ceil(Math.max(...ys) - y + 12);
    const density = 1.12;
    const bitmap = surface(Math.ceil(w * density), Math.ceil(h * density));
    const ctx = bitmap.getContext('2d');
    ctx.setTransform(bitmap.width / w, 0, 0, bitmap.height / h, -x * bitmap.width / w, -y * bitmap.height / h);
    return { chains, x, y, w, h, bitmap, ctx, mask: -1 };
  }

  let model;
  function geometry(anchors) {
    if (model && anchors === model.anchors) return model;
    if (!anchors || anchors.length !== 9) return null;
    if (model && anchors.every((a, i) => a.y === model.anchors[i].y && a.r === model.anchors[i].r)) return model;
    const chains = anchors.flatMap((a, i) => [makeChain(a, i, -1), makeChain(a, i, 1)]);
    const byStorey=anchors.map((_,idx)=>{
      const near=chains.filter(c=>c.front && c.level===idx);
      return near.length ? layer(near) : null;
    });
    model = { anchors, chains, behind: layer(chains.filter(c => !c.front)), byStorey };
    return model;
  }

  function chainLayer(ctx, l, levels, ages) {
    let mask = 0;
    for (const c of l.chains) if (levels[c.level] >= 0.999) mask |= 1 << c.level;
    if (l.mask !== mask) {
      l.ctx.clearRect(l.x - 1, l.y - 1, l.w + 2, l.h + 2);
      for (const c of l.chains) {
        const bright = !!(mask & (1 << c.level));
        darkIron(l.ctx, c);
        if (bright) litIron(l.ctx, c, 1);
        eye(l.ctx, c, bright);
      }
      l.mask = mask;
    }
    ctx.drawImage(l.bitmap, l.x, l.y, l.w, l.h);
    for (const c of l.chains) {
      const v = levels[c.level];
      if (v > 0.001 && v < 0.999) litIron(ctx, c, v);
      const age = ages[c.level];
      if (age >= 0 && age < 1.65) chainWave(ctx, c, age);
    }
  }

  function chainWave(ctx, c, age) {
    const u = clamp((age - 0.12) / 1.32, 0, 1);
    const envelope = Math.min(1, age * 5) * clamp((1.65 - age) * 3.1, 0, 1);
    if (!envelope) return;
    const alpha = ctx.globalAlpha;
    const pts = [];
    const tail = Math.max(0, u - 26 / c.length);
    for (let j = 0; j <= 7; j++) pts.push(point(c, tail + (u - tail) * j / 7));
    const streak = new Path2D();
    partPath(streak, pts, false);
    ctx.globalAlpha = alpha * envelope;
    stroke(ctx, streak, 'rgba(' + TowerPalette[c.level].mid + ',.28)', 4.5 * c.size);
    stroke(ctx, streak, 'rgb(' + TowerPalette[c.level].light + ')', 1.1 * c.size);
    const q = point(c, u);
    glow(ctx, c.level, q.x, q.y, 8 * c.size, 6 * c.size, 0.85);
    ctx.globalAlpha = alpha;
  }

  function lightning(ctx, m, t) {
    const elapsed = t - 7.65;
    if (elapsed < 0) return;
    const cycle = Math.floor(elapsed / 17.4);
    const age = elapsed - cycle * 17.4;
    if (age > 0.64) return;
    const c = m.chains[[12,15,10,17][cycle % 4]];
    const q = point(c, 0.45 + (cycle % 3) * 0.07);
    const side = Math.sign(q.x);
    const start = { x: q.x + side * (91 + 12 * (cycle % 4)), y: -716 - (cycle % 3) * 15 };
    const points = [];
    const zig = [0,6,0,10,-3,-9,13,4,17,-4,-12,1,-6,-17,0];
    for (let j = 0; j < zig.length; j++) {
      const u = j / (zig.length - 1);
      points.push({ x: start.x * (1 - u) + q.x * u + side * zig[j], y: start.y * (1 - u) + q.y * u });
    }
    const path = new Path2D();
    partPath(path, points, false);
    const v = points[8], twigs = new Path2D();
    partPath(twigs, [v, { x: v.x + 12 * side, y: v.y + 17 }, { x:v.x + 8 * side, y:v.y + 26 }, { x:v.x + 20 * side, y:v.y + 35 }], false);
    const envelope = Math.min(1, age / 0.085) * Math.pow(1 - age / 0.64, 2);
    const a = ctx.globalAlpha;
    ctx.globalAlpha = a * envelope;
    stroke(ctx, path, 'rgba(255,72,65,0.16)', 7.2);
    stroke(ctx, path, '#f48579', 1.7);
    stroke(ctx, path, '#ffdbad', 0.78);
    stroke(ctx, twigs, 'rgba(249,137,126,0.65)', 0.74);
    glow(ctx, 'flame', q.x, q.y, 21, 14, 0.65);
    ctx.globalAlpha = a;
  }

  function meanLevel(levels) {
    let s = 0;
    for (let i = 0; i < 9; i++) s += levels[i];
    return clamp(s / 9, 0, 1);
  }

  function back(ctx, t, levels, ages, anchors) {
    const m=geometry(anchors);
    if (!m) return;
    ctx.save();
    const energy=meanLevel(levels);
    sky(ctx,t,energy,levels[8],true);
    pier(ctx,piers[0],energy);
    pier(ctx,piers[1],energy);
    chainLayer(ctx,m.behind,levels,ages);
    lightning(ctx,m,t);
    // These supports are in front of the rear chains. The near chains are
    // subsequently drawn into their open iron eyes, in storey order.
    pier(ctx,piers[2],energy);
    pier(ctx,piers[3],energy);
    ctx.restore();
  }

  function nearChains(ctx, levels, ages, anchors, floor) {
    const near=geometry(anchors)?.byStorey[floor];
    if(!near) return;
    ctx.save();
    chainLayer(ctx,near,levels,ages);
    ctx.restore();
  }

  function front(ctx, t, levels) {
    ctx.save();
    sky(ctx,t,meanLevel(levels),levels[8],false);
    ctx.restore();
  }

  global.TowerSeals = { ground, back, nearChains, front, ready };

  function sealImageData() {
    return {"pillar": "", "ground": "", "sky": ""};
  }
})(sealModule);

/* Light scattered through the air on the two sides of the tower. All nine floor
   plates use a common projection, so complementary colours meet between eaves. */
const PrismLight = (() => {
  const layout = {"scale":0.68,"layers":[[1,264,283,-194.941,-258.118],[286,253,240,-184.647,-322.824],[528,227,217,-162.588,-389.0],[747,210,196,-155.235,-447.824],[945,191,176,-142.0,-497.824],[1123,175,163,-131.706,-544.882],[1288,165,151,-122.882,-589.0],[1441,150,136,-108.176,-627.235],[1579,135,256,-94.941,-859.588]]};
  const originX = -217, originY = -889, density = layout.scale;
  const image = new Image();
  const ready = new Promise((resolve,reject) => {
    image.onload = resolve;
    image.onerror = () => reject(new Error('琉璃光场素材读取失败'));
    image.src = new URL('assets/light/prism.webp', document.currentScript?.src || document.baseURI).href;
  });
  const fields=[null,null];
  function makeField() {
    const surface = document.createElement('canvas');
    surface.width = Math.ceil(434*density);
    surface.height = Math.ceil(1046*density);
    return {surface, brush:surface.getContext('2d'), mask:-1, bounds:null};
  }
  function rect(entry,near) {
    const [row,w,h,left,top]=entry;
    return {sx:near ? w+3 : 1, sy:row, w, h,
      x:Math.round((left-originX)*density), y:Math.round((top-originY)*density)};
  }
  const plates=[false,true].map(near=>layout.layers.map(entry=>rect(entry,near)));
  function build(field,list,mask) {
    const c=field.brush;
    c.clearRect(0,0,field.surface.width,field.surface.height);
    c.globalCompositeOperation='lighter';
    let x=field.surface.width, y=field.surface.height, right=0, bottom=0;
    for(let i=0;i<list.length;i++) {
      if (!(mask & (1<<i))) continue;
      const a=list[i];
      c.drawImage(image,a.sx,a.sy,a.w,a.h,a.x,a.y,a.w,a.h);
      x=Math.min(x,a.x); y=Math.min(y,a.y);
      right=Math.max(right,a.x+a.w); bottom=Math.max(bottom,a.y+a.h);
    }
    field.bounds = mask ? {x,y,w:right-x,h:bottom-y} : null;
    field.mask=mask;
  }
  function draw(ctx,levels,near) {
    if (!image.naturalWidth) return;
    let mask=0, transitioning=false;
    for(let i=0;i<levels.length;i++) {
      if (levels[i]>=.9999) mask |= 1<<i;
      else if(levels[i]>.0001) transitioning=true;
    }
    if (!mask && !transitioning) return;
    const side=near ? 1 : 0, list=plates[side];
    const field=fields[side] || (fields[side]=makeField());
    if (mask!==field.mask) build(field,list,mask);
    ctx.save();
    ctx.globalCompositeOperation='lighter';
    ctx.translate(originX,originY);
    ctx.scale(1/density,1/density);
    const b=field.bounds, alpha=ctx.globalAlpha;
    if (b) ctx.drawImage(field.surface,b.x,b.y,b.w,b.h,b.x,b.y,b.w,b.h);
    if (transitioning) for(let i=0;i<list.length;i++) {
      if (levels[i]<=.0001 || (mask & (1<<i))) continue;
      const a=list[i];
      ctx.globalAlpha=alpha*levels[i];
      ctx.drawImage(image,a.sx,a.sy,a.w,a.h,a.x,a.y,a.w,a.h);
    }
    ctx.restore();
  }
  return {ready,draw};
})();

/* The suspended seals turn on nine cylinders. Their two visible halves are drawn
   on opposite sides of the building. The map uses a 30-degree orthographic view. All coordinates use the tower footprint. */
const TowerRunes = (() => {
  'use strict';
  const atlasDir = new URL('assets/runes/', document.currentScript?.src || document.baseURI);
  const wheel = 2 * Math.PI;
  // Twelve bays give the open brush strokes enough angular separation to read.
  const count = 12;
  const tileW = 144, tileH = 80, variants = 6;
  const art = {};
  const ready = Promise.all(['blood', 'glass', 'cutlight'].map(name => new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => { art[name] = image; resolve(); };
    image.onerror = () => reject(new Error('符文材质加载失败：seal-' + name));
    image.src = new URL('seal-' + name + '.webp', atlasDir).href;
  })));
  const blood = {deep:[50,4,16], mid:[160,20,37], light:[222,53,62], core:[254,111,106]};
  const circle = Array.from({length:count}, (_, i) => {
    const theta = i * wheel / count;
    return { sin:Math.sin(theta), cos:Math.cos(theta) };
  });
  const rgba = (c, a) => 'rgba(' + c.join(',') + ',' + a + ')';

  function canvas(w,h) {
    const s = document.createElement('canvas'); s.width=w; s.height=h; return s;
  }

  function glowTile(p) {
    const s=canvas(88,88), c=s.getContext('2d');
    const g=c.createRadialGradient(44,44,0,44,44,44);
    g.addColorStop(0,rgba(p.light,.88)); g.addColorStop(.18,rgba(p.mid,.68));
    g.addColorStop(.51,rgba(p.mid,.26)); g.addColorStop(1,rgba(p.mid,0));
    c.fillStyle=g; c.fillRect(0,0,88,88); return s;
  }

  // Surface light from the ring, with an empty centre. Clouds of transmitted
  // colour flare out at the oblique sides, where the glass is seen edge-on.
  function optic(p, r, ry, back, lit) {
    const w=Math.ceil((r+20)*2), h=Math.ceil(ry*2+51);
    const s=canvas(w,h), c=s.getContext('2d');
    c.translate(w/2,h/2);
    const gl=glowTile(p);
    // Transmitted colour hugs the horizontal ring. Its long axis follows the
    // projected tangent rather than forming a vertical shaft through the map.
    const startAngle=back ? Math.PI : 0;
    for(let j=0;j<9;j++){
      const angle=startAngle+(j+.5)*Math.PI/9;
      const sx=Math.cos(angle), sy=Math.sin(angle);
      const tangent=Math.atan2(ry*sx,-r*sy);
      const segment=Math.hypot(r*sy,ry*sx)*Math.PI/9;
      const band=lit ? 12+3*Math.abs(sx) : 8;
      c.save();
      c.translate(r*sx,ry*sy);
      c.rotate(tangent);
      c.globalAlpha=(lit ? .39 : .115)*(back ? .72 : .89);
      c.drawImage(gl,-segment*.9,-band,segment*1.8,band*2);
      c.restore();
    }
    c.globalAlpha=1;
    const side=c.createLinearGradient(-r,0,r,0);
    const amount=back ? .63 : 1;
    // A fine Fresnel edge appears at the extremities, leaving clear gaps between inscriptions.
    const cut=lit&&!back
      ? [[0,.89],[.06,.76],[.20,.44],[.38,.34],[.55,.27],[.69,.37],[.83,.50],[.92,.74],[1,.87]]
      : [[0,.89],[.06,.74],[.19,.36],[.38,.17],[.56,.15],[.72,.26],[.92,.72],[1,.87]];
    for(const [pos,opacity] of cut) side.addColorStop(pos,rgba(p.light,opacity*amount*(lit ? .9 : .64)));
    const begin=back ? Math.PI : 0;
    c.strokeStyle=side;
    function cutEdge(dy,rad,width,pieces) {
      c.beginPath();
      for(const [from,to] of pieces) {
        const start=begin+from*Math.PI,finish=begin+to*Math.PI;
        c.moveTo(rad*Math.cos(start),dy+ry*Math.sin(start));
        c.ellipse(0,dy,rad,ry,0,start,finish);
      }
      c.lineWidth=width;c.stroke();
    }
    const top=lit&&!back?[[0,.245],[.263,.422],[.447,.691],[.707,.856],[.871,1]]:[[0,1]];
    const bottom=lit&&!back?[[0,.158],[.183,.354],[.37,.571],[.605,.775],[.793,1]]:[[0,1]];
    cutEdge(-4.9,r,lit&&!back ? .99 : .83,top);
    cutEdge(5.3,r*.994,lit&&!back ? .72 : .55,bottom);
    return {surface:s,w,h};
  }

  function flashSprite(p) {
    const s=canvas(76,48),c=s.getContext('2d');
    c.drawImage(glowTile(p),0,7,76,34);
    const ripple=c.createLinearGradient(4,0,72,0);
    ripple.addColorStop(0,rgba(p.light,0)); ripple.addColorStop(.44,rgba(p.light,.65));
    ripple.addColorStop(.5,rgba(p.core,1)); ripple.addColorStop(.56,rgba(p.light,.66));
    ripple.addColorStop(1,rgba(p.light,0));
    c.fillStyle=ripple;
    c.beginPath(); c.moveTo(3,23.8); c.lineTo(37,22.7); c.lineTo(73,23.8); c.lineTo(38,24.8); c.closePath(); c.fill();
    c.fillStyle=rgba(p.core,1); c.beginPath();
    c.moveTo(38,18); c.lineTo(39.1,23); c.lineTo(44,23.7); c.lineTo(39,24.4); c.lineTo(38,30); c.lineTo(37.3,24.6); c.lineTo(32.8,24); c.lineTo(37,23.3);c.closePath();c.fill();
    return s;
  }

  let layout, anchorIdentity, lastT=NaN;
  function init(anchors) {
    if (layout && anchors === anchorIdentity) return;
    if (layout && anchors.every((a,k) => a.eaveR===layout[k].eaveR && a.ringY===layout[k].cy && a.depthScale===layout[k].depthScale)) { anchorIdentity=anchors; return; }
    anchorIdentity=anchors;
    layout=anchors.map((a,k) => {
      const eaveR=a.eaveR;
      const radius=eaveR*1.19+2, depthScale=a.depthScale, ry=radius*depthScale;
      const ramp=TowerPalette[k];
      const ring={k,eaveR,radius,depthScale,ry,cy:a.ringY,
        // The taller glyphs on the lower tiers can be read even against the entrance.
        stampH:(39+eaveR*.097)*Math.sqrt(1-depthScale*depthScale), span:wheel*radius/count, row:k*tileH,
        marks:Array.from({length:count}, () => ({sin:0,cos:0,x:0,y:0})),
        optics:[false,true].map(rear=>[optic(blood,radius,ry,rear,false),optic(ramp,radius,ry,rear,true)]),
        flash:flashSprite(ramp),scratch:null,lastLight:-1};
      return ring;
    });
    lastT=NaN;
  }

  function poses(t) {
    if (lastT===t) return;
    for(const r of layout){
      // Full-turn periods differ from the eaves and alternate by storey.
      const t0=t*(r.k%2===0?1:-1)*wheel/(82+r.k*1.9)+r.k*.389+.12;
      const ca=Math.cos(t0),sa=Math.sin(t0);
      for(let j=0;j<count;j++){
        const pre=circle[j],m=r.marks[j];
        m.sin=sa*pre.cos+ca*pre.sin; m.cos=ca*pre.cos-sa*pre.sin;
        m.x=r.radius*m.sin; m.y=r.cy+r.ry*m.cos;
      }
    }
    lastT=t;
  }

  function selectRow(r,light) {
    if(light<=.0001) return {image:art.blood,y:r.row};
    if(light>=.9999) return {image:art.glass,y:r.row};
    if(!r.scratch) r.scratch=canvas(tileW*variants,tileH);
    if(light!==r.lastLight){
      const c=r.scratch.getContext('2d'),w=r.scratch.width;
      c.clearRect(0,0,w,tileH); c.globalCompositeOperation='lighter';
      c.globalAlpha=1-light; c.drawImage(art.blood,0,r.row,w,tileH,0,0,w,tileH);
      c.globalAlpha=light; c.drawImage(art.glass,0,r.row,w,tileH,0,0,w,tileH);
      c.globalAlpha=1; r.lastLight=light;
    }
    return {image:r.scratch,y:0};
  }

  function drawOptic(ctx, pair, x, y, light) {
    const alpha=ctx.globalAlpha;
    for(let n=0;n<2;n++){
      const weight=n ? light : 1-light;
      if(weight<=0) continue;
      const a=pair[n];
      ctx.globalAlpha=alpha*weight;
      ctx.drawImage(a.surface,x-a.w/2,y-a.h/2);
    }
    ctx.globalAlpha=alpha;
  }

  function drawHalf(ctx,t,levels,ages,anchors,rear,storey) {
    if(!art.glass || !art.blood || !anchors?.length) return;
    init(anchors);poses(t);
    ctx.save();
    const incoming=ctx.globalAlpha;
    const first=storey===undefined ? 0 : storey;
    const end=storey===undefined ? layout.length : first+1;
    for(let i=first;i<end;i++){
      const r=layout[i];
      const light=levels[i];
      const row=selectRow(r,light);
      drawOptic(ctx,r.optics[rear ? 1 : 0],0,r.cy,light);
      for(let j=0;j<count;j++){
        const m=r.marks[j];
        const facing=Math.abs(m.cos);
        if((m.cos<0)!==rear || facing<=.014) continue;
        // Below one-twelfth frontal width the refraction fades to zero before culling.
        const edge=Math.min(1,(facing-.014)/(.085-.014));
        const transmission=edge*edge*(3-2*edge);
        ctx.save();
        ctx.globalAlpha=incoming*(.67+.33*m.cos)*transmission;
        // The tangent foreshortens and tilts the character as it turns away.
        // A rear glyph reads through the reverse face of the transparent crystal.
        ctx.transform(r.span*m.cos/tileW,-r.span*r.depthScale*m.sin/tileW,0,r.stampH*(1-.12*light)/tileH,m.x,m.y);
        const variant=(j+r.k)%variants;
        ctx.drawImage(row.image,variant*tileW,row.y,tileW,tileH,-tileW/2,-tileH/2,tileW,tileH);
        // Fixed scene illumination moves along the engraved lip as its glass
        // face rotates. Only the cut surface has this reflection.
        const alignment=Math.max(0,m.cos*.82-m.sin*.57);
        if(light>0 && alignment>.62){
          const q=(alignment-.62)/.38;
          ctx.globalCompositeOperation='lighter';
          ctx.globalAlpha=incoming*light*transmission*.26*q*q;
          ctx.drawImage(art.cutlight,variant*tileW/2,r.row/2,tileW/2,tileH/2,
            -tileW/2,-tileH/2,tileW,tileH);
        }
        ctx.restore();
      }
      // A single caustic reflection travels around the seal during unlocking.
      const age=ages[r.k];
      if(age>=0 && age<1.35){
        const u=age/1.35, smooth=u*u*(3-2*u);
        const theta=(r.k%2===0?1:-1)*(-1.12+smooth*wheel);
        const d=Math.cos(theta),ss=Math.sin(theta);
        if((d<0)===rear){
          const face=Math.abs(d), edge=Math.min(1,face/.34);
          const roll=.55+.45*edge*edge*(3-2*edge);
          const a=Math.min(1,age*7,(1.35-age)*6)*(.68+.32*d)*roll;
          // At tangency the entire narrow caustic clears the roof silhouette.
          ctx.globalAlpha=incoming*a; const w=21+24*face;
          ctx.drawImage(r.flash,r.radius*ss-w/2,r.cy+r.ry*d-10,w,20);
          ctx.globalAlpha=incoming;
        }
      }
    }
    ctx.restore();
  }

  return {
    ready,
    back:(ctx,t,levels,ages,anchors,index)=>drawHalf(ctx,t,levels,ages,anchors,true,index),
    front:(ctx,t,levels,ages,anchors,index)=>drawHalf(ctx,t,levels,ages,anchors,false,index)
  };
})();

/* Public Canvas 2D API. Coordinates use the center of the tower footprint. */
(() => {
  'use strict';
  const body = TowerBody;
  const seals = sealModule.TowerSeals;
  const count = TowerPalette.length;
  const levels = new Float32Array(count);
  const origin = new Float32Array(count);
  const goals = new Uint8Array(count);
  const started = new Float64Array(count).fill(-Infinity);
  const flashed = new Float64Array(count).fill(-Infinity);
  const requested = new Uint8Array(count);
  const ages = new Float64Array(count);
  let target = 0;
  let lastTime = -Infinity;

  function floorCount(n) {
    const value = Number(n);
    return Number.isFinite(value) ? Math.min(count, Math.max(0, Math.trunc(value))) : 0;
  }

  function setLit(n, immediate = false) {
    target = floorCount(n);
    if (!immediate) return;
    for (let i = 0; i < count; i++) {
      levels[i] = origin[i] = goals[i] = i < target ? 1 : 0;
      started[i] = flashed[i] = -Infinity;
      requested[i] = 0;
    }
  }

  function flash(n) {
    if (Number.isInteger(n) && n >= 1 && n <= count) requested[n - 1] = 1;
  }

  function step(t) {
    if (t < lastTime) {
      // A scene clock can restart on map re-entry. Preserve the saved progress.
      setLit(target, true);
    }
    lastTime = t;
    for (let i = 0; i < count; i++) {
      const progress = Math.min(1, Math.max(0, (t - started[i]) / 0.72));
      const ease = progress * progress * (3 - 2 * progress);
      levels[i] = origin[i] + (goals[i] - origin[i]) * ease;
      const next = i < target ? 1 : 0;
      if (next !== goals[i]) {
        origin[i] = levels[i];
        goals[i] = next;
        started[i] = t;
        flashed[i] = next ? t : -Infinity;
      }
      if (requested[i]) {
        flashed[i] = t;
        requested[i] = 0;
      }
      ages[i] = t - flashed[i];
    }
  }

  // Contact and cast shadows project onto the ground at the same 30° camera angle.
  // Build them once. Their axial symmetry stays fixed while the individual floors turn.
  const shadow=document.createElement('canvas');
  shadow.width=500; shadow.height=215;
  const brush=shadow.getContext('2d');
  brush.translate(160,81);
  const groundShadow=brush.createLinearGradient(-35,-8,239,59);
  groundShadow.addColorStop(0,'rgba(27,17,25,.25)');
  groundShadow.addColorStop(.61,'rgba(25,15,25,.17)');
  groundShadow.addColorStop(1,'rgba(36,23,34,.025)');
  brush.fillStyle=groundShadow;
  brush.shadowColor='rgba(24,15,25,.23)';
  brush.shadowBlur=10;
  brush.beginPath();
  brush.moveTo(-122,-17);
  brush.lineTo(-72,-59);brush.lineTo(19,-61);brush.lineTo(164,-9);
  brush.lineTo(228,15);brush.lineTo(270,44);brush.lineTo(256,57);
  brush.lineTo(147,71);brush.lineTo(57,71);brush.lineTo(-49,55);
  brush.lineTo(-116,25);brush.closePath();brush.fill();
  brush.shadowBlur=0;
  function pool(x,y,width,height,shade) {
    brush.save();brush.translate(x,y);brush.scale(width,height);
    const g=brush.createRadialGradient(0,0,0,0,0,1);
    g.addColorStop(0,'rgba(15,12,19,'+shade+')');
    g.addColorStop(.49,'rgba(17,13,20,'+shade*.82+')');
    g.addColorStop(.75,'rgba(24,16,25,'+shade*.36+')');
    g.addColorStop(1,'rgba(31,21,30,0)');
    brush.fillStyle=g;brush.fillRect(-1,-1,2,2);brush.restore();
  }
  pool(1,3,152,77,.79);
  pool(5,6,132,61,.45);

  function draw(ctx, x, y, scale, t, pose) {
    if (!(scale > 0) || !Number.isFinite(t)) return;
    if (!pose) step(t);
    const lights = pose ? pose.levels : levels;
    const sweeps = pose ? pose.ages : ages;
    ctx.save();
    try {
      ctx.translate(x, y);
      ctx.scale(scale, scale);
      const anchors=body.anchors;
      seals.ground(ctx, lights);
      ctx.drawImage(shadow, -160, -81);
      BloodPillars.draw(ctx,t,lights,false);
      seals.back(ctx,t,lights,sweeps,anchors);
      PrismLight.draw(ctx,lights,false);
      // At a common screen position the higher world plane is nearer the camera.
      // A roof on the next floor therefore occludes the preceding storey's ring.
      body.draw(ctx,t,lights,sweeps,{
        beforeFloor(g,index) {
          TowerRunes.back(g,t,lights,sweeps,anchors,index);
        },
        afterFloor(g,index) {
          seals.nearChains(g,lights,sweeps,anchors,index);
          TowerRunes.front(g,t,lights,sweeps,anchors,index);
        }
      });
      PrismLight.draw(ctx,lights,true);
      BloodPillars.draw(ctx,t,lights,true);
      seals.front(ctx,t,lights);
    } finally {
      ctx.restore();
    }
  }

  window.TOWER3D = Object.freeze({
    ready: Promise.all([body.ready, seals.ready, TowerRunes.ready, PrismLight.ready, BloodPillars.ready]),
    floors: Object.freeze(TowerPalette.map(({name, boss, light}) =>
      Object.freeze({colorName:name, boss, color:'rgb(' + light.join(',') + ')'}))),
    setLit, flash, draw
  });
})();

})();
